// Some portions generated by Claude Code
package org.eclipse.rdf4j.query.algebra.evaluation.impl;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.query.QueryLanguage;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryOptimizerTest;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.SameTermFilterOptimizer;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.parser.QueryParserUtil;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * @author jeen
 */
public class SameTermFilterOptimizerTest extends QueryOptimizerTest {

	@Override
	public SameTermFilterOptimizer getOptimizer() {
		return new SameTermFilterOptimizer();
	}

	/**
	 * SES-1685: the {@code sameTerm} filter that closes a cyclic path must stay on the path. Inlining it would rename
	 * one endpoint to the other; replacing it is left to {@code ReflexiveStarPathOptimizer}, which runs after join
	 * ordering.
	 */
	@ParameterizedTest
	@ValueSource(strings = {
			"SELECT ?s { ?s <urn:p>* ?s }",
			"SELECT ?s { ?s a <urn:C> . ?s <urn:p>* ?s }",
			"SELECT ?s { ?s <urn:p>+ ?s }",
			"SELECT ?a { ?a <urn:p>* ?b FILTER sameTerm(?a, ?b) }"
	})
	public void sameTermOverThePathEndpointsStaysInPlace(String query) {
		TupleExpr before = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		assertThat(before.toString()).contains("Filter", "SameTerm", "ArbitraryLengthPath");
		TupleExpr expr = before.clone();

		getOptimizer().optimize(expr, null, EmptyBindingSet.getInstance());

		assertThat(expr).isEqualTo(before);
		assertThat(expr.toString()).isEqualTo(before.toString());
	}

}
